import json
import os

import mcp.types as types
from polymarket_mcp import server as upstream

# Demo mode alone still creates API credentials in this upstream revision.
os.environ["DEMO_MODE"] = "true"
os.environ["CANCEL_ON_SHUTDOWN"] = "false"
original_load_config = upstream.load_config


def load_readonly_config():
    return original_load_config().model_copy(update={
        "POLYMARKET_API_KEY": None,
        "POLYMARKET_API_SECRET": None,
        "POLYMARKET_PASSPHRASE": None,
        "POLYMARKET_API_KEY_NAME": None,
        "ENABLE_AUTONOMOUS_TRADING": False,
    })


async def reject_credentials(self, *args, **kwargs):
    raise RuntimeError("Wallet authentication is disabled in this Localish service")


upstream.server.name = "polymarket-readonly"
upstream.load_config = load_readonly_config
upstream.PolymarketClient.create_api_credentials = reject_credentials
public_tools = upstream.market_discovery.get_tools()
# Upstream exposes a holder-analysis placeholder that requires authentication.
public_tools += [tool for tool in upstream.market_analysis.get_tools()
                 if tool.name != "get_market_holders"]
public_realtime = {
    "subscribe_market_prices", "subscribe_orderbook_updates",
    "subscribe_market_resolution", "get_realtime_status", "unsubscribe_realtime",
}
public_tools += [tool for tool in upstream.realtime.get_tools() if tool.name in public_realtime]
allowed = {tool.name for tool in public_tools}
original_call_tool = upstream.call_tool


@upstream.server.list_tools()
async def list_tools():
    return public_tools


@upstream.server.call_tool()
async def call_tool(name, arguments):
    # Enforce the boundary on direct calls too; hiding tools is not authorization.
    if name not in allowed:
        return types.CallToolResult(isError=True, content=[types.TextContent(
            type="text", text="This Localish service only supports public market research."
        )])
    content = await original_call_tool(name, arguments)
    failed = False
    for item in content:
        if item.type != "text":
            continue
        try:
            payload = json.loads(item.text)
        except (ValueError, TypeError):
            failed |= item.text.startswith("Error:")
        else:
            failed |= isinstance(payload, dict) and (
                "error" in payload or payload.get("success") is False
            )
    # Localish health checks consume MCP isError, not JSON embedded in text.
    return types.CallToolResult(content=content, isError=failed)


if __name__ == "__main__":
    upstream.run()
